questions.solution:
import numpy as np


def weight_scale(n_inputs, n_neurons, init="he"):
    """Standard deviation of the initial weights of a dense layer."""
    if init == "he":
        return np.sqrt(2.0 / n_inputs)
    elif init == "xavier" or init == "glorot":
        return np.sqrt(2.0 / (n_inputs + n_neurons))
    elif init == "small":
        return 0.01
    raise ValueError(f"unknown init: {init!r}")
